import { Component, ViewChild, ChangeDetectionStrategy, ChangeDetectorRef } from '@angular/core';
import { RequestDirective } from 'app/utils/table/request/request.directive';
import { NotificationsService } from 'app/services/notifications';
import { useLoader } from 'app/utils/loader/decorators';
import { ModalService } from 'app/utils/modals/modal.service';
import { WordpressIncident } from '@imunify360-api/wordpress-incidents';
import { TableComponent } from 'app/utils/table/component/table.component';
import { firstValueFrom, take } from 'rxjs';
import { WordPressPluginService } from 'app/services/wordpress-plugin.service';
import { WordpressRulesService } from 'app/services/wordpress-rules.service';
import { PermissionsService } from 'app/services/permissions';
import { DisableRuleModalComponent, DisableRuleModalResult, DisableRuleModalData } from './disable-rule-modal/disable-rule-modal.component';

declare const IS_WORDPRESS_PLUGIN: boolean;

@Component({
    templateUrl: './cms-incidents.component.html',
    styleUrls: ['./cms-incidents.component.scss'],
    changeDetection: ChangeDetectionStrategy.OnPush,
})
export class CmsIncidentsComponent {
    @ViewChild(RequestDirective, { static: true }) request: RequestDirective;
    @ViewChild(TableComponent, { static: true }) table: TableComponent;

    userDomains: { [key: string]: string };

    constructor(
        private cdr: ChangeDetectorRef,
        private wordpressRulesService: WordpressRulesService,
        public notifications: NotificationsService,
        public wordPressPluginService: WordPressPluginService,
        private modalService: ModalService,
        public permissions: PermissionsService,
    ) {
        this.loadDomainsList();
    }

    async blockRule(incident: WordpressIncident) {
        const dialogResult = await this.modalService.open<DisableRuleModalResult, DisableRuleModalData>(
            DisableRuleModalComponent,
            {
                data: { ruleToBlock: incident },
            }
        );

        if (!dialogResult) {
            return;
        }

        await this.performBlockRule(incident, dialogResult.domains);
    }

    @useLoader
    private async performBlockRule(incident: WordpressIncident, domains: string[]) {
        await firstValueFrom(this.wordpressRulesService.disable({
            rule: incident.rule,
            domains: domains.length > 0 ? domains : undefined
        }));
        const notificationKey = typeof IS_WORDPRESS_PLUGIN === 'boolean' && IS_WORDPRESS_PLUGIN
            ? 'notifications.ruleActionDelayed'
            : 'notifications.ruleAction';
        await this.notifications.success(notificationKey, null, { action: 'disabled' });
        await this.request.load();
    }

    private loadDomainsList(): void {
        this.wordPressPluginService.getDomainsListForTableWidget()
            .pipe(take(1))
            .subscribe(userDomains => {
                this.userDomains = userDomains;
                this.cdr.markForCheck();
            });
    }
}
