import { NgModule } from '@angular/core';
import { RouterModule } from '@angular/router';
import { CommonModule } from '@angular/common';
import { I360NavigationTabsModule } from 'app/components/navigation-tabs/navigation-tabs.module';
import { I360TableModule } from 'app/utils/table/table.module';
import { I360TranslateModule } from 'app/utils/translate/translate.module';
import { CmsProtectionComponent } from './cms-protection.component';
import { CMS_PROTECTION_TABS } from './cms-protection-tabs.enum';
import { CmsIncidentsModule } from './incidents/cms-incidents.module';
import { CmsIncidentsComponent } from './incidents/cms-incidents.component';
import { DisabledRulesComponent } from './disabled-rules/disabled-rules.component';
import { WordpressRulesService } from 'app/services/wordpress-rules.service';
import { DisabledRulesModule } from './disabled-rules/disabled-rules.module';


@NgModule({
    imports: [
        RouterModule,
        CommonModule,
        I360TableModule,
        I360NavigationTabsModule,
        I360TranslateModule,
        CmsIncidentsModule,
        DisabledRulesModule,
        RouterModule.forChild([{
                path: '',
                component: CmsProtectionComponent,
                children: [
                    { path: '', redirectTo: CMS_PROTECTION_TABS.Incidents, pathMatch: 'full' },
                    { path: CMS_PROTECTION_TABS.Incidents, component: CmsIncidentsComponent },
                    { path: CMS_PROTECTION_TABS.DisabledRules, component: DisabledRulesComponent },
                ],
            }]),
    ],
    providers: [
        WordpressRulesService,
    ],
    declarations: [
        CmsProtectionComponent
    ],
    exports: [
        CmsProtectionComponent
    ]
})
export class CmsProtectionModule {}
