import { ChangeDetectionStrategy, ChangeDetectorRef, Component, TemplateRef, ViewChild, ViewEncapsulation } from '@angular/core';
import { useLoader } from 'app/utils/loader/decorators';
import { NotificationsService } from 'app/services/notifications';
import { ModalService } from 'app/utils/modals/modal.service';
import { RequestDirective } from 'app/utils/table/request/request.directive';
import { WordpressRulesService } from 'app/services/wordpress-rules.service';
import { WordpressRule } from '@imunify360-api/wordpress-plugin';
import { firstValueFrom, take } from 'rxjs';
import { WordPressPluginService } from 'app/services/wordpress-plugin.service';
import { PermissionsService } from 'app/services/permissions';

declare const IS_WORDPRESS_PLUGIN: boolean;

@Component({
    selector: 'i360-wordpress-disabled-rules',
    styleUrls: ['./disabled-rules.component.scss'],
    templateUrl: './disabled-rules.component.html',
    changeDetection: ChangeDetectionStrategy.OnPush,
    encapsulation: ViewEncapsulation.None,
})
export class DisabledRulesComponent {
    @ViewChild(RequestDirective, {static: true}) request: RequestDirective;
    @ViewChild('modal', {static: true}) modalBody: TemplateRef<WordpressRule>;

    isWordpressPlugin = typeof IS_WORDPRESS_PLUGIN === 'boolean' && IS_WORDPRESS_PLUGIN;
    imunifyPackage = IMUNIFY_PACKAGE;
    userDomains: { [key: string]: string };

    constructor(
        private cdr: ChangeDetectorRef,
        public wordpressRulesService: WordpressRulesService,
        private notifications: NotificationsService,
        private modalService: ModalService,
        private userDomainsService: WordPressPluginService,
        public permissions: PermissionsService,
    ) {
        this.loadDomainsList();
    }

    async enable(rule: WordpressRule) {
        const dialogResult = await this.modalService.open(this.modalBody, {
            id: 'enable-rule',
            data: rule,
        });
        if (dialogResult === false) {
            return;
        }

        await this.performEnable(rule);
    }

    @useLoader
    private async performEnable(rule: WordpressRule) {
        await firstValueFrom(this.wordpressRulesService.enable(rule));
        const notificationKey = this.isWordpressPlugin
            ? 'notifications.ruleActionDelayed'
            : 'notifications.ruleAction';
        await this.notifications.success(notificationKey, null, {action: 'enabled'});
        await this.request.load();
    }

    private loadDomainsList(): void {
        this.userDomainsService.getDomainsListForTableWidget()
            .pipe(take(1))
            .subscribe(userDomains => {
                this.userDomains = userDomains;
                delete this.userDomains['all'];
                this.cdr.markForCheck();
            });
    }
}
