import { Component } from '@angular/core';
import { NAVBAR_TABS } from 'app/components/nav-root/navbar-items.enum';
import { CMS_PROTECTION_TABS } from './cms-protection-tabs.enum';
import { isSubTabAllowed } from 'app/utils/allowed-items.utils';

@Component({
    selector: 'i360-cms-protection',
    templateUrl: './cms-protection.component.html',
    styleUrls: ['./cms-protection.component.scss'],
})
export class CmsProtectionComponent {
    CMS_PROTECTION_TABS = CMS_PROTECTION_TABS;

    constructor() {}

    isTabAllowed(tab: CMS_PROTECTION_TABS): boolean {
        return isSubTabAllowed(NAVBAR_TABS.CMSProtection, tab);
    }
}
