import { Injectable } from '@angular/core';
import { XHR } from 'app/utils/xhr/xhr';
import { WordPressPluginAPI, WordpressRule } from '@imunify360-api/wordpress-plugin';

@Injectable()
export class WordpressRulesService {
    constructor(public xhr: XHR) {}

    enable = this.xhr.rx(WordPressPluginAPI.enableRule);
    disable = this.xhr.rx(WordPressPluginAPI.disableRule);
    _get = this.xhr.rx(WordPressPluginAPI.listRules);
    list = this.xhr.wrap(this._get, WordpressRule);
}
