import { Component, Input, OnChanges, ViewChild } from '@angular/core';
import { WidgetDirective } from 'app/utils/table/widgets/widget';
import { DropdownWidgetHeaderComponent } from 'app/utils/table/widgets/headers/dropdown';
import { TypeOfValueListWidgetValue } from 'app/utils/table/widgets/widget-list';

@Component({
    selector: 'i360-widget[i360-domains]',
    template: `
        <i360-dropdown-widget-header
            *i360HostTemplate="let widget"
            [widget]="widget"></i360-dropdown-widget-header>
        <i360-widget-value *i360HostTemplate="'value'; let widget" [widget]="widget">
            <ng-container *ngFor="let value of widget.value; let last=last">
                {{ value }}<ng-container *ngIf="!last">,</ng-container>
            </ng-container>
        </i360-widget-value>
    `,
})
export class DomainsWidgetComponent implements OnChanges {
    readonly delegatePriority = 2.5;
    @Input() availableValues: { [key: string]: string };
    @ViewChild(DropdownWidgetHeaderComponent, {static: false})
    header: DropdownWidgetHeaderComponent;

    constructor(public widget: WidgetDirective) {
        widget.delegate = new TypeOfValueListWidgetValue(widget);
        widget.delegate = this;
        widget.emptyValue = [];
        widget.paramName = 'domains';
        widget.debugCssClass = 'i360-domains';
        this.widget.title = 'utils.table.widgets.content.by_domain.title';
    }

    ngOnChanges(): void {
        this.widget.availableValues = this.availableValues;
    }

    setValue(value?, reload?) {
        if (reload) {
            this.header.dropdown.open();
        }
    }
}
