import { Component, Input, ChangeDetectionStrategy } from '@angular/core';

@Component({
    selector: 'i360-wordpress-rule-cell',
    templateUrl: './wordpress-rule-cell.component.html',
    changeDetection: ChangeDetectionStrategy.OnPush,
})
export class WordpressRuleCellComponent {
    @Input() ruleId: string;
    @Input() fallbackName?: string;
    @Input() cveLink: string | null;

    get displayName(): string {
        return this.fallbackName || this.ruleId;
    }
}
