import { Component, Input, OnChanges } from '@angular/core';
import { WidgetDirective } from 'app/utils/table/widgets/widget';
import { DelegateResult, SetValueForRequest } from 'app/utils/table/widgets/delegate';


@Component({
    selector: 'i360-widget[i360-by-domain]',
    template: `
        <i360-dropdown-widget-header
                *i360HostTemplate="let widget"
                [widget]="widget">
        </i360-dropdown-widget-header>
        <i360-set-widget-value></i360-set-widget-value>
    `,
})
export class ByDomainWidgetComponent implements OnChanges, SetValueForRequest {
    readonly delegatePriority = 3;
    @Input() availableValues: { [key: string]: string };

    constructor(public widget: WidgetDirective) {
        this.widget.delegate = this;
        this.widget.paramName = 'by_domain';
        this.widget.emptyValue = '';
        this.widget.defaultValue = '';
        this.widget.debugCssClass = 'i360-by_domain';
        this.widget.title = 'utils.table.widgets.content.by_domain.title';
    }

    ngOnChanges(): void {
        this.widget.availableValues = this.availableValues;
    }

    setValueForRequest(request: any): void|DelegateResult {
        if (this.widget.value === 'all') {
            delete request[this.widget.paramName];
            return new DelegateResult;
        }
    }
}
