import { ChangeDetectionStrategy, Component, Inject } from '@angular/core';
import { FormControl } from '@angular/forms';
import { MAT_DIALOG_DATA, MatDialogRef } from '@angular/material/dialog';
import { WordpressIncident } from '@imunify360-api/wordpress-incidents';
import { WordPressPluginService } from 'app/services/wordpress-plugin.service';
import { map } from 'rxjs';
import { ModalEntry } from 'app/utils/modals/entry';

declare const IS_WORDPRESS_PLUGIN: boolean;

export interface DisableRuleModalData {
    ruleToBlock: WordpressIncident;
}

export interface DisableRuleModalResult {
    domains: string[];
}

@Component({
    selector: 'i360-disable-rule-modal',
    templateUrl: './disable-rule-modal.component.html',
    styleUrls: ['./disable-rule-modal.component.scss'],
    changeDetection: ChangeDetectionStrategy.OnPush,
})
export class DisableRuleModalComponent extends ModalEntry<DisableRuleModalData, DisableRuleModalResult> {
    isWordpressPlugin = typeof IS_WORDPRESS_PLUGIN === 'boolean' && IS_WORDPRESS_PLUGIN;

    domains$ = this.wordpressPluginService.getDomainsList().pipe(
        map(domains => (domains || []).map(d => d.domain)),
    );

    domainsControl = new FormControl<string[]>([]);

    constructor(
        @Inject(MAT_DIALOG_DATA) public data: DisableRuleModalData,
        public dialogRef: MatDialogRef<DisableRuleModalComponent, DisableRuleModalResult | false>,
        private wordpressPluginService: WordPressPluginService,
    ) {
        super();
    }

    onConfirm(): void {
        this.dialogRef.close({
            domains: this.domainsControl.value || []
        });
    }
}
